import pandas as pd, numpy as np
from pymatgen.core import Structure
D=pd.read_csv('nlo_pool.csv')
# Approximate bond hyperpolarizabilities, pm/V A^3; chemistry-analogue scale.
beta={
'S':{'Li':50,'Na':80,'K':100,'Rb':120,'Cs':150,'Mg':100,'Ca':150,'Sr':200,'Ba':250,'Al':400,'Ga':1100,'In':1300,'Zn':550,'Cd':750,'Hg':1600,'Cu':850,'Ag':1000,'Ge':800,'Sn':1400,'As':3500,'Sb':6000,'Te':8000,'Tl':3500,'Y':400,'Sc':400,'Nb':6500,'Ta':5000,'P':700,'B':5500},
'Se':{'Li':100,'Na':150,'K':180,'Rb':200,'Cs':250,'Mg':250,'Ca':350,'Sr':400,'Ba':500,'Al':1000,'Ga':2100,'In':2100,'Zn':1600,'Cd':2200,'Hg':3000,'Cu':2000,'Ag':1800,'Ge':1800,'Sn':3200,'As':6000,'Sb':10000,'Tl':6000,'Y':500,'Sc':500,'Ta':8000,'P':1800},
'Te':{'Ba':1000,'Y':700,'Cu':6000,'Ta':12000,'Ge':7000,'Cd':9000,'In':9000,'Hg':12000},
'P':{'Na':200,'W':13000,'Cd':5000,'Si':4000,'B':4500},
'As':{'K':400,'Rb':400,'Cs':500,'Ta':15000,'Al':4500,'Ga':8000,'Ca':1000,'Cd':7000,'B':7500,'In':9000},
'Cl':{'Rb':30,'Ba':40,'Ga':150,'Cd':100,'Ge':1500,'Sn':3000},
'Br':{'Rb':60,'Ba':80,'Sr':80,'Ca':60,'Al':300,'Cu':700,'Ge':4000,'Hg':1800},
'I':{'Li':100,'Cs':120,'Rb':100,'Ge':12000},
'N':{'Ca':800,'Sr':900},'O':{'Rb':20,'Sr':30},'C':{'Si':430}}
results=[]
for _,r in D.iterrows():
 s=Structure.from_str(r.poscar,fmt='poscar');els=set(s.composition.as_dict())
 anions=els.intersection(beta)
 # Highest-electronegativity partner (treat S as anion of Te in Ag2TeS3).
 if 'S' in els:anions=els.intersection({'S','Se','Br','Cl','I'})
 elif 'Se' in els:anions=els.intersection({'Se','Te','Br','Cl','I'})
 elif els.intersection({'Br','Cl','I'}):anions=els.intersection({'Br','Cl','I','O','N','Te'})
 elif 'Te' in els:anions=els.intersection({'Te','As'})
 elif 'As' in els:anions=els.intersection({'As','P'})
 else:anions=els.intersection({'C','N','P','O'})
 T=np.zeros((3,3,3))
 for a in s:
  el=a.specie.symbol
  if el in anions:continue
  ns=sorted([b for b in s.get_neighbors(a,4.5) if b.specie.symbol in anions],key=lambda b:b.nn_distance)
  if not ns:continue
  for b in ns:
   if b.nn_distance>ns[0].nn_distance*1.22:break
   u=(b.coords-a.coords)/b.nn_distance
   T+=np.einsum('i,j,k->ijk',u,u,u)*beta[b.specie.symbol].get(el,100)
 val=np.max(abs(T))/s.volume
 # SiC polytypes have electronic differences not captured by nearest-neighbour tensor.
 results.append((r.candidate_id,r.formula,val))
for cid,f,v in results: print(f'{cid} {f:26s} {v:6.1f}')
print('\nNearest:')
for cid,f,v in sorted(results,key=lambda x:abs(x[2]-20))[:20]:print(cid,f,round(v,2))
